begin;
-- Curriculum batch 5/18; lessons 73-90
insert into public.academy_lessons(id,course_id,title,slug,summary,content_html,starter_code,exercise,status,sort_order,estimated_minutes)
select x.id,c.id,x.title,x.slug,x.summary,x.content_html,x.starter_code,x.exercise,x.status,x.sort_order,x.estimated_minutes
from jsonb_to_recordset($lessons$[{"id":"curriculum-324-html-advanced-01","course_id":"html-advanced","title":"طراحی معماری معنایی برای صفحات چندبخشی","slug":"html-advanced-01","summary":"یک صفحه بزرگ باید با بخش‌های معنایی روشن، ترتیب منطقی و روابط قابل فهم ساخته شود؛ این معماری هم پیمایش را آسان می‌کند و هم نگهداری را. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>یک صفحه بزرگ باید با بخش‌های معنایی روشن، ترتیب منطقی و روابط قابل فهم ساخته شود؛ این معماری هم پیمایش را آسان می‌کند و هم نگهداری را.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;header&gt;برند&lt;/header&gt;&lt;nav aria-label=\"راهنمای اصلی\"&gt;&lt;a href=\"#guide\"&gt;راهنما&lt;/a&gt;&lt;/nav&gt;&lt;main id=\"guide\"&gt;&lt;article&gt;&lt;h1&gt;راهنمای محصول&lt;/h1&gt;&lt;section aria-labelledby=\"install\"&gt;&lt;h2 id=\"install\"&gt;نصب&lt;/h2&gt;&lt;p&gt;مراحل نصب محصول.&lt;/p&gt;&lt;/section&gt;&lt;/article&gt;&lt;aside aria-label=\"مطالب مرتبط\"&gt;پیوندهای مرتبط&lt;/aside&gt;&lt;/main&gt;&lt;footer&gt;پایان صفحه&lt;/footer&gt;</code></pre><h3>تمرین</h3><p>یک صفحه مستندات با header، nav، main، article، دو section و footer بساز؛ ترتیب را طوری بچین که با خاموش بودن CSS هم قابل فهم باشد.</p><h3>نکته فنی</h3><p>عنصرهای معنایی را به‌خاطر ظاهر انتخاب نکن؛ هر عنصر باید نقش محتوایی واقعی داشته باشد.</p><h3>معیار موفقیت</h3><p>صفحه با landmarkهای درست و بدون چند main هم‌زمان ساخته شده باشد.</p>","starter_code":"<header>برند</header><nav aria-label=\"راهنمای اصلی\"><a href=\"#guide\">راهنما</a></nav><main id=\"guide\"><article><h1>راهنمای محصول</h1><section aria-labelledby=\"install\"><h2 id=\"install\">نصب</h2><p>مراحل نصب محصول.</p></section></article><aside aria-label=\"مطالب مرتبط\">پیوندهای مرتبط</aside></main><footer>پایان صفحه</footer>","exercise":"یک صفحه مستندات با header، nav، main، article، دو section و footer بساز؛ ترتیب را طوری بچین که با خاموش بودن CSS هم قابل فهم باشد.","status":"published","sort_order":1,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-02","course_id":"html-advanced","title":"مدل‌سازی landmarkهای صفحه و ناحیه‌های مستقل","slug":"html-advanced-02","summary":"Landmarkها نقاط پرش اصلی صفحه‌اند. برای ناحیه‌های تکراری یا چندگانه باید نام قابل فهم تعیین کنی تا صفحه‌خوان بتواند آن‌ها را از هم جدا کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>Landmarkها نقاط پرش اصلی صفحه‌اند. برای ناحیه‌های تکراری یا چندگانه باید نام قابل فهم تعیین کنی تا صفحه‌خوان بتواند آن‌ها را از هم جدا کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;nav aria-label=\"ناوبری اصلی\"&gt;...&lt;/nav&gt;&lt;nav aria-label=\"مسیر صفحه\"&gt;...&lt;/nav&gt;&lt;main&gt;...&lt;/main&gt;&lt;aside aria-label=\"فیلتر نتایج\"&gt;...&lt;/aside&gt;</code></pre><h3>تمرین</h3><p>سه nav مستقل برای منوی اصلی، مسیر راهنما و صفحه‌بندی بساز و برای هرکدام نام دقیق و غیرتکراری قرار بده.</p><h3>نکته فنی</h3><p>برای landmarkهای هم‌نوع، نام‌گذاری مبهم مثل «منو» کافی نیست.</p><h3>معیار موفقیت</h3><p>هر ناحیه با نامش از ناحیه‌های دیگر قابل تشخیص باشد.</p>","starter_code":"<nav aria-label=\"ناوبری اصلی\">...</nav><nav aria-label=\"مسیر صفحه\">...</nav><main>...</main><aside aria-label=\"فیلتر نتایج\">...</aside>","exercise":"سه nav مستقل برای منوی اصلی، مسیر راهنما و صفحه‌بندی بساز و برای هرکدام نام دقیق و غیرتکراری قرار بده.","status":"published","sort_order":2,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-03","course_id":"html-advanced","title":"نام‌گذاری دسترس‌پذیر با name و role و value","slug":"html-advanced-03","summary":"دسترس‌پذیری فقط متن جایگزین نیست؛ کنترل باید نام، نقش و مقدار قابل تشخیص داشته باشد. عنصر بومی معمولاً این اطلاعات را بهتر از نقش‌سازی دستی فراهم می‌کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>دسترس‌پذیری فقط متن جایگزین نیست؛ کنترل باید نام، نقش و مقدار قابل تشخیص داشته باشد. عنصر بومی معمولاً این اطلاعات را بهتر از نقش‌سازی دستی فراهم می‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;label for=\"volume\"&gt;بلندی صدا&lt;/label&gt;&lt;input id=\"volume\" type=\"range\" min=\"0\" max=\"100\" value=\"40\"&gt;&lt;button type=\"button\" aria-pressed=\"false\"&gt;زیرنویس&lt;/button&gt;</code></pre><h3>تمرین</h3><p>یک کنترل تنظیم صدا و دکمه روشن/خاموش زیرنویس بساز؛ نام قابل مشاهده و وضعیت دکمه را درست نمایش بده.</p><h3>نکته فنی</h3><p>روی div نقش دکمه نگذار وقتی می‌توانی button واقعی استفاده کنی.</p><h3>معیار موفقیت</h3><p>نام کنترل‌ها واضح باشد و وضعیت toggle با aria-pressed هماهنگ تغییر کند.</p>","starter_code":"<label for=\"volume\">بلندی صدا</label><input id=\"volume\" type=\"range\" min=\"0\" max=\"100\" value=\"40\"><button type=\"button\" aria-pressed=\"false\">زیرنویس</button>","exercise":"یک کنترل تنظیم صدا و دکمه روشن/خاموش زیرنویس بساز؛ نام قابل مشاهده و وضعیت دکمه را درست نمایش بده.","status":"published","sort_order":3,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-04","course_id":"html-advanced","title":"ساخت جدول داده‌های پیچیده با scope و id","slug":"html-advanced-04","summary":"در جدول پیچیده، scope به مرورگر می‌گوید سرستون به کدام محور مربوط است؛ برای ارتباط‌های پیچیده‌تر از id و headers استفاده می‌شود. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>در جدول پیچیده، scope به مرورگر می‌گوید سرستون به کدام محور مربوط است؛ برای ارتباط‌های پیچیده‌تر از id و headers استفاده می‌شود.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;table&gt;&lt;caption&gt;فروش ماهانه&lt;/caption&gt;&lt;tr&gt;&lt;th scope=\"col\"&gt;ماه&lt;/th&gt;&lt;th scope=\"col\"&gt;فروش&lt;/th&gt;&lt;/tr&gt;&lt;tr&gt;&lt;th scope=\"row\"&gt;مهر&lt;/th&gt;&lt;td&gt;120&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;</code></pre><h3>تمرین</h3><p>جدولی برای گزارش سه منطقه و دو فصل بساز؛ سرستون‌های ردیف و ستون را مشخص کن و caption بنویس.</p><h3>نکته فنی</h3><p>جدول را برای چیدمان صفحه استفاده نکن؛ فقط داده‌های جدولی.</p><h3>معیار موفقیت</h3><p>هر سلول داده سرستون مرتبط و قابل تشخیص داشته باشد.</p>","starter_code":"<table><caption>فروش ماهانه</caption><tr><th scope=\"col\">ماه</th><th scope=\"col\">فروش</th></tr><tr><th scope=\"row\">مهر</th><td>120</td></tr></table>","exercise":"جدولی برای گزارش سه منطقه و دو فصل بساز؛ سرستون‌های ردیف و ستون را مشخص کن و caption بنویس.","status":"published","sort_order":4,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-05","course_id":"html-advanced","title":"پیوند دادن سرستون‌های چندسطحی جدول","slug":"html-advanced-05","summary":"وقتی سرستون‌ها چند سطح دارند، headers می‌تواند رابطه دقیق سلول داده با چند سرستون را روشن کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>وقتی سرستون‌ها چند سطح دارند، headers می‌تواند رابطه دقیق سلول داده با چند سرستون را روشن کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;table&gt;&lt;tr&gt;&lt;th id=\"year\" colspan=\"2\"&gt;۱۴۰۵&lt;/th&gt;&lt;/tr&gt;&lt;tr&gt;&lt;th id=\"q1\"&gt;سه‌ماهه اول&lt;/th&gt;&lt;th id=\"q2\"&gt;سه‌ماهه دوم&lt;/th&gt;&lt;/tr&gt;&lt;tr&gt;&lt;th id=\"sales\"&gt;فروش&lt;/th&gt;&lt;td headers=\"year q1 sales\"&gt;۸۰&lt;/td&gt;&lt;td headers=\"year q2 sales\"&gt;۹۵&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;</code></pre><h3>تمرین</h3><p>یک جدول با گروه‌بندی سال، فصل و شاخص بساز و برای سلول داده headers دقیق تعریف کن.</p><h3>نکته فنی</h3><p>مقدار headers باید به id سرستون‌های موجود اشاره کند.</p><h3>معیار موفقیت</h3><p>تمام شناسه‌ها یکتا و ارجاع‌ها معتبر باشند.</p>","starter_code":"<table><tr><th id=\"year\" colspan=\"2\">۱۴۰۵</th></tr><tr><th id=\"q1\">سه‌ماهه اول</th><th id=\"q2\">سه‌ماهه دوم</th></tr><tr><th id=\"sales\">فروش</th><td headers=\"year q1 sales\">۸۰</td><td headers=\"year q2 sales\">۹۵</td></tr></table>","exercise":"یک جدول با گروه‌بندی سال، فصل و شاخص بساز و برای سلول داده headers دقیق تعریف کن.","status":"published","sort_order":5,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-06","course_id":"html-advanced","title":"الگوی توضیح خطا برای فرم‌های بزرگ","slug":"html-advanced-06","summary":"در فرم‌های طولانی، خطا باید هم کنار فیلد و هم در خلاصه‌ای قابل پیمایش ارائه شود؛ توضیح خطا باید به ورودی مرتبط باشد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>در فرم‌های طولانی، خطا باید هم کنار فیلد و هم در خلاصه‌ای قابل پیمایش ارائه شود؛ توضیح خطا باید به ورودی مرتبط باشد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;label for=\"email\"&gt;ایمیل کاری&lt;/label&gt;&lt;input id=\"email\" type=\"email\" aria-describedby=\"email-help email-error\"&gt;&lt;p id=\"email-help\"&gt;برای دریافت رسید استفاده می‌شود.&lt;/p&gt;&lt;p id=\"email-error\"&gt;نشانی واردشده معتبر نیست.&lt;/p&gt;</code></pre><h3>تمرین</h3><p>فرم ثبت‌نام سه فیلدی بساز که برای هر فیلد راهنما و پیام خطای جداگانه داشته باشد و با aria-describedby متصل شوند.</p><h3>نکته فنی</h3><p>فقط رنگ قرمز برای اعلام خطا کافی نیست.</p><h3>معیار موفقیت</h3><p>هر پیام خطا متنی، مرتبط و قابل دسترسی باشد.</p>","starter_code":"<label for=\"email\">ایمیل کاری</label><input id=\"email\" type=\"email\" aria-describedby=\"email-help email-error\"><p id=\"email-help\">برای دریافت رسید استفاده می‌شود.</p><p id=\"email-error\">نشانی واردشده معتبر نیست.</p>","exercise":"فرم ثبت‌نام سه فیلدی بساز که برای هر فیلد راهنما و پیام خطای جداگانه داشته باشد و با aria-describedby متصل شوند.","status":"published","sort_order":6,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-07","course_id":"html-advanced","title":"اعتبارسنجی گروهی و نمایش خلاصه خطاها","slug":"html-advanced-07","summary":"برای فرم‌های بزرگ، خلاصه خطاها کاربر را به اولین ورودی نامعتبر هدایت می‌کند؛ لینک‌ها باید به id واقعی فیلدها بروند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>برای فرم‌های بزرگ، خلاصه خطاها کاربر را به اولین ورودی نامعتبر هدایت می‌کند؛ لینک‌ها باید به id واقعی فیلدها بروند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;section aria-labelledby=\"errors\"&gt;&lt;h2 id=\"errors\"&gt;موارد نیازمند اصلاح&lt;/h2&gt;&lt;ul&gt;&lt;li&gt;&lt;a href=\"#user-email\"&gt;ایمیل را بررسی کن&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;label for=\"user-email\"&gt;ایمیل&lt;/label&gt;&lt;input id=\"user-email\" type=\"email\"&gt;</code></pre><h3>تمرین</h3><p>یک فرم پنج فیلدی طراحی کن و خلاصه خطاها را با پیوند به فیلدهای دارای مشکل نمایش بده.</p><h3>نکته فنی</h3><p>خلاصه خطا باید بعد از اعتبارسنجی به‌روزرسانی شود؛ HTML تنها منطق پویا را اجرا نمی‌کند.</p><h3>معیار موفقیت</h3><p>هر پیوند خطا به فیلد متناظر برسد و پیام مشخص داشته باشد.</p>","starter_code":"<section aria-labelledby=\"errors\"><h2 id=\"errors\">موارد نیازمند اصلاح</h2><ul><li><a href=\"#user-email\">ایمیل را بررسی کن</a></li></ul></section><label for=\"user-email\">ایمیل</label><input id=\"user-email\" type=\"email\">","exercise":"یک فرم پنج فیلدی طراحی کن و خلاصه خطاها را با پیوند به فیلدهای دارای مشکل نمایش بده.","status":"published","sort_order":7,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-08","course_id":"html-advanced","title":"ساخت کنترل سفارشی متصل به فرم","slug":"html-advanced-08","summary":"فرم‌های سفارشی می‌توانند با ElementInternals به چرخه فرم مرورگر وصل شوند؛ این API به JavaScript و custom element نیاز دارد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>فرم‌های سفارشی می‌توانند با ElementInternals به چرخه فرم مرورگر وصل شوند؛ این API به JavaScript و custom element نیاز دارد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>class XCode extends HTMLElement{static formAssociated=true;#internals=this.attachInternals();connectedCallback(){this.#internals.setFormValue(this.getAttribute('value')||'');}}customElements.define('x-code',XCode);</code></pre><h3>تمرین</h3><p>نمونه را در فایل JavaScript کنار HTML اجرا کن؛ یک custom element فرم‌پذیر بساز و توضیح بده چرا تعریف آن فقط با HTML ممکن نیست.</p><h3>نکته فنی</h3><p>form-associated custom elements قابلیت پیشرفته مرورگر است و باید پشتیبانی هدف بررسی شود.</p><h3>معیار موفقیت</h3><p>عنصر سفارشی مقدار را به فرم ارسال کند و محدودیت پشتیبانی مستند شود.</p>","starter_code":"class XCode extends HTMLElement{static formAssociated=true;#internals=this.attachInternals();connectedCallback(){this.#internals.setFormValue(this.getAttribute('value')||'');}}customElements.define('x-code',XCode);","exercise":"نمونه را در فایل JavaScript کنار HTML اجرا کن؛ یک custom element فرم‌پذیر بساز و توضیح بده چرا تعریف آن فقط با HTML ممکن نیست.","status":"published","sort_order":8,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-09","course_id":"html-advanced","title":"مدیریت چرخه فوکوس در رابط‌های modal","slug":"html-advanced-09","summary":"در پنجره modal باید فوکوس داخل پنجره بماند، با Escape بسته شود و پس از بسته‌شدن به کنترل آغازگر برگردد؛ dialog بومی بسیاری از این رفتارها را فراهم می‌کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>در پنجره modal باید فوکوس داخل پنجره بماند، با Escape بسته شود و پس از بسته‌شدن به کنترل آغازگر برگردد؛ dialog بومی بسیاری از این رفتارها را فراهم می‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;button id=\"open-dialog\" type=\"button\"&gt;باز کردن&lt;/button&gt;\n&lt;dialog id=\"confirm-dialog\"&gt;\n  &lt;p&gt;ادامه می‌دهی؟&lt;/p&gt;\n  &lt;button id=\"close-dialog\" type=\"button\"&gt;بستن&lt;/button&gt;\n&lt;/dialog&gt;\n&lt;script&gt;\n  const dialog = document.querySelector(\"#confirm-dialog\");\n  const openButton = document.querySelector(\"#open-dialog\");\n  const closeButton = document.querySelector(\"#close-dialog\");\n  openButton.addEventListener(\"click\", () =&gt; dialog.showModal());\n  closeButton.addEventListener(\"click\", () =&gt; dialog.close());\n&lt;/script&gt;</code></pre><h3>تمرین</h3><p>پنجره تأیید بساز؛ بازگشت فوکوس به دکمه آغازگر و رفتار Escape را در مرورگر آزمایش کن.</p><h3>نکته فنی</h3><p>dialog را با display:block شبیه‌سازی نکن؛ حالت modal واقعی تفاوت دارد.</p><h3>معیار موفقیت</h3><p>فوکوس هنگام بازشدن مدیریت شود و پس از بستن به آغازگر بازگردد.</p>","starter_code":"<button id=\"open-dialog\" type=\"button\">باز کردن</button>\n<dialog id=\"confirm-dialog\">\n  <p>ادامه می‌دهی؟</p>\n  <button id=\"close-dialog\" type=\"button\">بستن</button>\n</dialog>\n<script>\n  const dialog = document.querySelector(\"#confirm-dialog\");\n  const openButton = document.querySelector(\"#open-dialog\");\n  const closeButton = document.querySelector(\"#close-dialog\");\n  openButton.addEventListener(\"click\", () => dialog.showModal());\n  closeButton.addEventListener(\"click\", () => dialog.close());\n</script>","exercise":"پنجره تأیید بساز؛ بازگشت فوکوس به دکمه آغازگر و رفتار Escape را در مرورگر آزمایش کن.","status":"published","sort_order":9,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-10","course_id":"html-advanced","title":"الگوی تعاملی popover با دسترس‌پذیری","slug":"html-advanced-10","summary":"Popover برای محتوای موقت مناسب است، اما trigger باید نام و وضعیت روشن داشته باشد و محتوای آن نباید مسیر اصلی کاربر را قطع کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>Popover برای محتوای موقت مناسب است، اما trigger باید نام و وضعیت روشن داشته باشد و محتوای آن نباید مسیر اصلی کاربر را قطع کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;button popovertarget=\"help\" aria-label=\"نمایش راهنما\"&gt;راهنما&lt;/button&gt;&lt;div id=\"help\" popover&gt;&lt;p&gt;راهنمای کوتاه این بخش&lt;/p&gt;&lt;/div&gt;</code></pre><h3>تمرین</h3><p>برای سه فیلد حساس راهنمای popover بساز و مشخص کن کدام محتوا باید همیشه روی صفحه بماند.</p><h3>نکته فنی</h3><p>popover جایگزین dialog برای تأییدهای مهم یا جریان چندمرحله‌ای نیست.</p><h3>معیار موفقیت</h3><p>باز و بسته شدن با trigger بومی کار کند و محتوا قابل پیمایش باشد.</p>","starter_code":"<button popovertarget=\"help\" aria-label=\"نمایش راهنما\">راهنما</button><div id=\"help\" popover><p>راهنمای کوتاه این بخش</p></div>","exercise":"برای سه فیلد حساس راهنمای popover بساز و مشخص کن کدام محتوا باید همیشه روی صفحه بماند.","status":"published","sort_order":10,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-11","course_id":"html-advanced","title":"ساخت مؤلفه‌های تکرارپذیر با template","slug":"html-advanced-11","summary":"template محتوای غیرفعال و قابل تکثیر نگه می‌دارد؛ محتوای آن تا زمان clone و درج در سند نمایش داده نمی‌شود. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>template محتوای غیرفعال و قابل تکثیر نگه می‌دارد؛ محتوای آن تا زمان clone و درج در سند نمایش داده نمی‌شود.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;template id=\"card-template\"&gt;\n  &lt;article class=\"card\"&gt;\n    &lt;h2&gt;&lt;/h2&gt;\n    &lt;p&gt;&lt;/p&gt;\n  &lt;/article&gt;\n&lt;/template&gt;\n&lt;div id=\"items\"&gt;&lt;/div&gt;\n&lt;script&gt;\n  const template = document.querySelector(\"#card-template\");\n  const itemsContainer = document.querySelector(\"#items\");\n  const card = template.content.cloneNode(true);\n  card.querySelector(\"h2\").textContent = \"درس HTML\";\n  card.querySelector(\"p\").textContent = \"ساختار سند\";\n  itemsContainer.append(card);\n&lt;/script&gt;</code></pre><h3>تمرین</h3><p>قالب کارت درس بساز و با JavaScript دو نسخه با داده‌های متفاوت تولید کن؛ داده را با textContent وارد کن.</p><h3>نکته فنی</h3><p>محتوای کاربر را با innerHTML وارد قالب نکن مگر پاک‌سازی معتبر انجام شده باشد.</p><h3>معیار موفقیت</h3><p>قالب اولیه در صفحه دیده نشود و کارت‌های clone شده درست نمایش یابند.</p>","starter_code":"<template id=\"card-template\">\n  <article class=\"card\">\n    <h2></h2>\n    <p></p>\n  </article>\n</template>\n<div id=\"items\"></div>\n<script>\n  const template = document.querySelector(\"#card-template\");\n  const itemsContainer = document.querySelector(\"#items\");\n  const card = template.content.cloneNode(true);\n  card.querySelector(\"h2\").textContent = \"درس HTML\";\n  card.querySelector(\"p\").textContent = \"ساختار سند\";\n  itemsContainer.append(card);\n</script>","exercise":"قالب کارت درس بساز و با JavaScript دو نسخه با داده‌های متفاوت تولید کن؛ داده را با textContent وارد کن.","status":"published","sort_order":11,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-12","course_id":"html-advanced","title":"ترکیب Web Components با slot","slug":"html-advanced-12","summary":"slot نقطه درج محتوا در Web Component است؛ نام slot باید با ویژگی slot در محتوای فرزند هماهنگ باشد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>slot نقطه درج محتوا در Web Component است؛ نام slot باید با ویژگی slot در محتوای فرزند هماهنگ باشد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;template id=\"card-template\"&gt;\n  &lt;article&gt;\n    &lt;h2&gt;&lt;slot name=\"name\"&gt;بدون نام&lt;/slot&gt;&lt;/h2&gt;\n    &lt;slot&gt;&lt;/slot&gt;\n  &lt;/article&gt;\n&lt;/template&gt;\n&lt;user-card&gt;\n  &lt;span slot=\"name\"&gt;سارا&lt;/span&gt;\n  &lt;p&gt;دانش‌آموز HTML&lt;/p&gt;\n&lt;/user-card&gt;\n&lt;script&gt;\n  class UserCard extends HTMLElement {\n    connectedCallback() {\n      if (this.shadowRoot) return;\n      const template = document.querySelector(\"#card-template\");\n      this.attachShadow({mode: \"open\"}).append(template.content.cloneNode(true));\n    }\n  }\n  customElements.define(\"user-card\", UserCard);\n&lt;/script&gt;</code></pre><h3>تمرین</h3><p>ساختار یک کارت با slot نام‌دار و slot پیش‌فرض طراحی کن و حالت محتوای جایگزین را توضیح بده.</p><h3>نکته فنی</h3><p>slot به‌تنهایی کامپوننت را فعال نمی‌کند؛ به custom element و shadow DOM نیاز است.</p><h3>معیار موفقیت</h3><p>محتوای نام‌دار و پیش‌فرض در جای درست قرار بگیرند.</p>","starter_code":"<template id=\"card-template\">\n  <article>\n    <h2><slot name=\"name\">بدون نام</slot></h2>\n    <slot></slot>\n  </article>\n</template>\n<user-card>\n  <span slot=\"name\">سارا</span>\n  <p>دانش‌آموز HTML</p>\n</user-card>\n<script>\n  class UserCard extends HTMLElement {\n    connectedCallback() {\n      if (this.shadowRoot) return;\n      const template = document.querySelector(\"#card-template\");\n      this.attachShadow({mode: \"open\"}).append(template.content.cloneNode(true));\n    }\n  }\n  customElements.define(\"user-card\", UserCard);\n</script>","exercise":"ساختار یک کارت با slot نام‌دار و slot پیش‌فرض طراحی کن و حالت محتوای جایگزین را توضیح بده.","status":"published","sort_order":12,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-13","course_id":"html-advanced","title":"تعریف قرارداد HTML برای custom elements","slug":"html-advanced-13","summary":"custom element باید نام دارای خط تیره داشته باشد و رفتار آن با چرخه عمر اتصال و جداشدن هماهنگ شود. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>custom element باید نام دارای خط تیره داشته باشد و رفتار آن با چرخه عمر اتصال و جداشدن هماهنگ شود.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>class LessonBadge extends HTMLElement{connectedCallback(){this.textContent=this.getAttribute('level')||'درس';}}customElements.define('lesson-badge',LessonBadge);</code></pre><h3>تمرین</h3><p>یک عنصر lesson-badge تعریف کن که ویژگی level را بخواند؛ رفتار آن را هنگام حذف و افزودن دوباره بررسی کن.</p><h3>نکته فنی</h3><p>نام‌های رزروشده یا بدون خط تیره برای custom element معتبر نیستند.</p><h3>معیار موفقیت</h3><p>عنصر بدون خطای ثبت تعریف شود و ویژگی level را نمایش دهد.</p>","starter_code":"class LessonBadge extends HTMLElement{connectedCallback(){this.textContent=this.getAttribute('level')||'درس';}}customElements.define('lesson-badge',LessonBadge);","exercise":"یک عنصر lesson-badge تعریف کن که ویژگی level را بخواند؛ رفتار آن را هنگام حذف و افزودن دوباره بررسی کن.","status":"published","sort_order":13,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-14","course_id":"html-advanced","title":"ساختاردهی داده‌های ساخت‌یافته با JSON-LD","slug":"html-advanced-14","summary":"JSON-LD داده ساخت‌یافته را از محتوای نمایشی جدا می‌کند؛ داده باید دقیقاً با محتوای قابل مشاهده صفحه هماهنگ باشد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>JSON-LD داده ساخت‌یافته را از محتوای نمایشی جدا می‌کند؛ داده باید دقیقاً با محتوای قابل مشاهده صفحه هماهنگ باشد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;script type=\"application/ld+json\"&gt;{\"@context\":\"https://schema.org\",\"@type\":\"Course\",\"name\":\"آموزش HTML پیشرفته\",\"description\":\"ساخت صفحات استاندارد\"}&lt;/script&gt;</code></pre><h3>تمرین</h3><p>برای صفحه یک دوره واقعی JSON-LD از نوع Course بساز و فقط اطلاعاتی را وارد کن که روی صفحه هم وجود دارد.</p><h3>نکته فنی</h3><p>داده ساخت‌یافته تضمین‌کننده نمایش نتیجه ویژه در جست‌وجو نیست.</p><h3>معیار موفقیت</h3><p>JSON معتبر باشد و ادعای نادرست یا محتوای پنهان نداشته باشد.</p>","starter_code":"<script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@type\":\"Course\",\"name\":\"آموزش HTML پیشرفته\",\"description\":\"ساخت صفحات استاندارد\"}</script>","exercise":"برای صفحه یک دوره واقعی JSON-LD از نوع Course بساز و فقط اطلاعاتی را وارد کن که روی صفحه هم وجود دارد.","status":"published","sort_order":14,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-15","course_id":"html-advanced","title":"مدیریت canonical و نسخه‌های تکراری صفحه","slug":"html-advanced-15","summary":"canonical نسخه ترجیحی یک محتوای تکراری را معرفی می‌کند؛ نشانی باید مطلق و به نسخه واقعی و قابل دسترس اشاره کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>canonical نسخه ترجیحی یک محتوای تکراری را معرفی می‌کند؛ نشانی باید مطلق و به نسخه واقعی و قابل دسترس اشاره کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;link rel=\"canonical\" href=\"https://example.com/academy/html-advanced\"&gt;</code></pre><h3>تمرین</h3><p>برای صفحه‌ای که با پارامترهای مرتب‌سازی باز می‌شود canonical تعریف کن و توضیح بده چه زمانی نباید به صفحه دیگری اشاره کند.</p><h3>نکته فنی</h3><p>canonical ابزار حل همه مشکلات duplicate content نیست و باید با redirect و نقشه سایت سازگار باشد.</p><h3>معیار موفقیت</h3><p>فقط یک canonical معتبر و همسو با URL اصلی وجود داشته باشد.</p>","starter_code":"<link rel=\"canonical\" href=\"https://example.com/academy/html-advanced\">","exercise":"برای صفحه‌ای که با پارامترهای مرتب‌سازی باز می‌شود canonical تعریف کن و توضیح بده چه زمانی نباید به صفحه دیگری اشاره کند.","status":"published","sort_order":15,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-16","course_id":"html-advanced","title":"چندزبانه‌سازی فنی با hreflang","slug":"html-advanced-16","summary":"hreflang نسخه‌های زبانی هم‌ارز را به موتور جست‌وجو معرفی می‌کند؛ پیوندها باید متقابل و کد زبان/منطقه معتبر باشند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>hreflang نسخه‌های زبانی هم‌ارز را به موتور جست‌وجو معرفی می‌کند؛ پیوندها باید متقابل و کد زبان/منطقه معتبر باشند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;link rel=\"alternate\" hreflang=\"fa\" href=\"https://example.com/fa/course\"&gt;&lt;link rel=\"alternate\" hreflang=\"en\" href=\"https://example.com/en/course\"&gt;&lt;link rel=\"alternate\" hreflang=\"x-default\" href=\"https://example.com/course\"&gt;</code></pre><h3>تمرین</h3><p>برای نسخه فارسی و انگلیسی یک مقاله، hreflang متقابل و x-default بساز و خطای URL نامتقارن را پیدا کن.</p><h3>نکته فنی</h3><p>hreflang زبان صفحه را عوض نمی‌کند؛ lang سند نیز باید درست باشد.</p><h3>معیار موفقیت</h3><p>هر نسخه به نسخه‌های هم‌ارز اشاره کند و URLها واقعی باشند.</p>","starter_code":"<link rel=\"alternate\" hreflang=\"fa\" href=\"https://example.com/fa/course\"><link rel=\"alternate\" hreflang=\"en\" href=\"https://example.com/en/course\"><link rel=\"alternate\" hreflang=\"x-default\" href=\"https://example.com/course\">","exercise":"برای نسخه فارسی و انگلیسی یک مقاله، hreflang متقابل و x-default بساز و خطای URL نامتقارن را پیدا کن.","status":"published","sort_order":16,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-17","course_id":"html-advanced","title":"بهینه‌سازی اشتراک‌گذاری با Open Graph","slug":"html-advanced-17","summary":"Open Graph عنوان، توضیح و تصویر اشتراک‌گذاری را کنترل می‌کند؛ تصویر باید قابل دسترس و متناسب با محتوای همان صفحه باشد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>Open Graph عنوان، توضیح و تصویر اشتراک‌گذاری را کنترل می‌کند؛ تصویر باید قابل دسترس و متناسب با محتوای همان صفحه باشد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;meta property=\"og:type\" content=\"article\"&gt;&lt;meta property=\"og:title\" content=\"HTML پیشرفته\"&gt;&lt;meta property=\"og:description\" content=\"ساخت صفحات وب استاندارد\"&gt;&lt;meta property=\"og:image\" content=\"https://example.com/images/html.jpg\"&gt;&lt;meta property=\"og:url\" content=\"https://example.com/html\"&gt;</code></pre><h3>تمرین</h3><p>برای یک درس، مجموعه Open Graph کامل بنویس و تفاوت آن را با meta description توضیح بده.</p><h3>نکته فنی</h3><p>اطلاعات Open Graph جایگزین title و description عادی نیست.</p><h3>معیار موفقیت</h3><p>عنوان، URL و تصویر با محتوای صفحه همخوان باشند.</p>","starter_code":"<meta property=\"og:type\" content=\"article\"><meta property=\"og:title\" content=\"HTML پیشرفته\"><meta property=\"og:description\" content=\"ساخت صفحات وب استاندارد\"><meta property=\"og:image\" content=\"https://example.com/images/html.jpg\"><meta property=\"og:url\" content=\"https://example.com/html\">","exercise":"برای یک درس، مجموعه Open Graph کامل بنویس و تفاوت آن را با meta description توضیح بده.","status":"published","sort_order":17,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-18","course_id":"html-advanced","title":"کنترل نمایه‌سازی با robots metadata","slug":"html-advanced-18","summary":"robots meta دستورهای نمایه‌سازی را برای خزنده‌ها اعلام می‌کند؛ این دستور دسترسی امنیتی ایجاد نمی‌کند و محرمانگی محتوا را تضمین نمی‌کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>robots meta دستورهای نمایه‌سازی را برای خزنده‌ها اعلام می‌کند؛ این دستور دسترسی امنیتی ایجاد نمی‌کند و محرمانگی محتوا را تضمین نمی‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;meta name=\"robots\" content=\"noindex,follow\"&gt;</code></pre><h3>تمرین</h3><p>برای صفحه ورود خصوصی دستور مناسب بنویس و توضیح بده چرا اطلاعات حساس نباید صرفاً با noindex محافظت شوند.</p><h3>نکته فنی</h3><p>برای محتوای محرمانه احراز هویت و کنترل دسترسی لازم است؛ robots.txt نیز ابزار امنیتی نیست.</p><h3>معیار موفقیت</h3><p>محدودیت نمایه‌سازی درست باشد و هیچ داده محرمانه‌ای در HTML عمومی قرار نگیرد.</p>","starter_code":"<meta name=\"robots\" content=\"noindex,follow\">","exercise":"برای صفحه ورود خصوصی دستور مناسب بنویس و توضیح بده چرا اطلاعات حساس نباید صرفاً با noindex محافظت شوند.","status":"published","sort_order":18,"estimated_minutes":40}]$lessons$::jsonb) as x(id text,course_id text,title text,slug text,summary text,content_html text,starter_code text,exercise text,status text,sort_order integer,estimated_minutes integer)
join (values
('html','html','beginner'),('html-intermediate','html','intermediate'),('html-advanced','html','advanced'),
('css','css','beginner'),('css-intermediate','css','intermediate'),('css-advanced','css','advanced'),
('javascript','javascript','beginner'),('javascript-intermediate','javascript','intermediate'),('javascript-advanced','javascript','advanced')
) as cp(course_id,language_id,level_id) on cp.course_id=x.course_id
join public.academy_courses c on c.language_id=cp.language_id and c.level_id=cp.level_id
on conflict(id) do update set title=excluded.title,slug=excluded.slug,summary=excluded.summary,content_html=excluded.content_html,starter_code=excluded.starter_code,exercise=excluded.exercise,status='published',sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,archived_at=null,updated_at=now();

-- NEXORA FORGE ACADEMY INSTALL — PART 8/21
-- Curriculum lessons 91-108 of 324

begin;
-- Curriculum batch 6/18; lessons 91-108
insert into public.academy_lessons(id,course_id,title,slug,summary,content_html,starter_code,exercise,status,sort_order,estimated_minutes)
select x.id,c.id,x.title,x.slug,x.summary,x.content_html,x.starter_code,x.exercise,x.status,x.sort_order,x.estimated_minutes
from jsonb_to_recordset($lessons$[{"id":"curriculum-324-html-advanced-19","course_id":"html-advanced","title":"امن‌سازی پیوندهای خروجی و پنجره جدید","slug":"html-advanced-19","summary":"لینک‌های بازشونده در تب جدید باید رفتارشان برای کاربر روشن باشد؛ rel مناسب از دسترسی صفحه مقصد به window.opener جلوگیری می‌کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>لینک‌های بازشونده در تب جدید باید رفتارشان برای کاربر روشن باشد؛ rel مناسب از دسترسی صفحه مقصد به window.opener جلوگیری می‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;a href=\"https://example.org\" target=\"_blank\" rel=\"noopener noreferrer\"&gt;منبع خارجی (در زبانه جدید)&lt;/a&gt;</code></pre><h3>تمرین</h3><p>سه لینک خارجی بساز؛ یکی در همان تب و دو مورد در تب جدید با توضیح قابل فهم برای کاربر.</p><h3>نکته فنی</h3><p>target blank بدون توضیح ممکن است کاربر را سردرگم کند؛ noopener را صریح بنویس.</p><h3>معیار موفقیت</h3><p>رفتار لینک اعلام شده و opener در دسترس صفحه مقصد نباشد.</p>","starter_code":"<a href=\"https://example.org\" target=\"_blank\" rel=\"noopener noreferrer\">منبع خارجی (در زبانه جدید)</a>","exercise":"سه لینک خارجی بساز؛ یکی در همان تب و دو مورد در تب جدید با توضیح قابل فهم برای کاربر.","status":"published","sort_order":19,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-20","course_id":"html-advanced","title":"سیاست امنیت محتوا و محدودیت‌های meta CSP","slug":"html-advanced-20","summary":"meta CSP فقط زیرمجموعه‌ای از سیاست امنیت محتوا را اعمال می‌کند و نسبت به هدر HTTP محدودیت دارد؛ سیاست سخت‌گیرانه باید در سرور تنظیم شود. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>meta CSP فقط زیرمجموعه‌ای از سیاست امنیت محتوا را اعمال می‌کند و نسبت به هدر HTTP محدودیت دارد؛ سیاست سخت‌گیرانه باید در سرور تنظیم شود.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'self'; img-src 'self' https:; object-src 'none'; base-uri 'self'\"&gt;</code></pre><h3>تمرین</h3><p>یک سیاست آزمایشی برای صفحه ایستا بنویس و مشخص کن چرا هدر HTTP برای سیاست نهایی ترجیح دارد.</p><h3>نکته فنی</h3><p>CSP را بدون آزمون منابع لازم فعال نکن؛ ممکن است اسکریپت‌ها و سبک‌های معتبر را مسدود کند.</p><h3>معیار موفقیت</h3><p>منابع مجاز محدود باشند و محدودیت meta CSP به‌درستی توضیح داده شود.</p>","starter_code":"<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'self'; img-src 'self' https:; object-src 'none'; base-uri 'self'\">","exercise":"یک سیاست آزمایشی برای صفحه ایستا بنویس و مشخص کن چرا هدر HTTP برای سیاست نهایی ترجیح دارد.","status":"published","sort_order":20,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-21","course_id":"html-advanced","title":"طراحی بارگذاری واکنشی رسانه‌های سنگین","slug":"html-advanced-21","summary":"رسانه واکنشی باید برای اندازه‌های مختلف فایل مناسب انتخاب کند؛ picture برای art direction و source type کاربرد دارد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>رسانه واکنشی باید برای اندازه‌های مختلف فایل مناسب انتخاب کند؛ picture برای art direction و source type کاربرد دارد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;picture&gt;&lt;source media=\"(max-width: 600px)\" srcset=\"small.webp\"&gt;&lt;source type=\"image/avif\" srcset=\"hero.avif\"&gt;&lt;img src=\"hero.jpg\" alt=\"نمای داشبورد آموزشی\" width=\"1200\" height=\"600\"&gt;&lt;/picture&gt;</code></pre><h3>تمرین</h3><p>برای تصویر قهرمان نسخه موبایل و دسکتاپ تعریف کن و fallback تصویری معتبر قرار بده.</p><h3>نکته فنی</h3><p>ابعاد را مشخص کن تا جابه‌جایی چیدمان کاهش یابد؛ alt را با محتوای واقعی هماهنگ کن.</p><h3>معیار موفقیت</h3><p>در مرورگرهای فاقد فرمت جدید، fallback نمایش داده شود.</p>","starter_code":"<picture><source media=\"(max-width: 600px)\" srcset=\"small.webp\"><source type=\"image/avif\" srcset=\"hero.avif\"><img src=\"hero.jpg\" alt=\"نمای داشبورد آموزشی\" width=\"1200\" height=\"600\"></picture>","exercise":"برای تصویر قهرمان نسخه موبایل و دسکتاپ تعریف کن و fallback تصویری معتبر قرار بده.","status":"published","sort_order":21,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-22","course_id":"html-advanced","title":"راهبرد preload و prefetch برای مسیرهای واقعی","slug":"html-advanced-22","summary":"preload برای منبعی است که همین صفحه قطعاً به‌زودی نیاز دارد؛ prefetch برای ناوبری احتمالی آینده است و مصرف شبکه دارد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>preload برای منبعی است که همین صفحه قطعاً به‌زودی نیاز دارد؛ prefetch برای ناوبری احتمالی آینده است و مصرف شبکه دارد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;link rel=\"preload\" href=\"/fonts/academy.woff2\" as=\"font\" type=\"font/woff2\" crossorigin&gt;&lt;link rel=\"prefetch\" href=\"/next-lesson.html\"&gt;</code></pre><h3>تمرین</h3><p>برای فونت ضروری preload و برای صفحه بعدی prefetch تعریف کن؛ هزینه بارگذاری بی‌مورد را بررسی کن.</p><h3>نکته فنی</h3><p>preload زیاد رقابت منابع را بالا می‌برد و می‌تواند عملکرد را بدتر کند.</p><h3>معیار موفقیت</h3><p>فقط منابع حیاتی preload شوند و نوع و crossorigin درست باشد.</p>","starter_code":"<link rel=\"preload\" href=\"/fonts/academy.woff2\" as=\"font\" type=\"font/woff2\" crossorigin><link rel=\"prefetch\" href=\"/next-lesson.html\">","exercise":"برای فونت ضروری preload و برای صفحه بعدی prefetch تعریف کن؛ هزینه بارگذاری بی‌مورد را بررسی کن.","status":"published","sort_order":22,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-23","course_id":"html-advanced","title":"مدیریت crossorigin در منابع خارجی","slug":"html-advanced-23","summary":"منابع cross-origin ممکن است به CORS نیاز داشته باشند؛ مقدار crossorigin باید با نوع منبع و پاسخ سرور سازگار باشد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>منابع cross-origin ممکن است به CORS نیاز داشته باشند؛ مقدار crossorigin باید با نوع منبع و پاسخ سرور سازگار باشد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;link rel=\"preload\" href=\"https://cdn.example.com/font.woff2\" as=\"font\" type=\"font/woff2\" crossorigin&gt;&lt;img src=\"https://cdn.example.com/chart.png\" alt=\"نمودار فروش\" crossorigin=\"anonymous\"&gt;</code></pre><h3>تمرین</h3><p>یک فونت و تصویر CDN تعریف کن؛ بررسی کن سرور چه هدر CORS لازم دارد و چه زمانی درخواست مسدود می‌شود.</p><h3>نکته فنی</h3><p>افزودن crossorigin به‌تنهایی مجوز سرور ایجاد نمی‌کند.</p><h3>معیار موفقیت</h3><p>درخواست با هدرهای مجاز پاسخ بگیرد و رفتار خطا توضیح داده شود.</p>","starter_code":"<link rel=\"preload\" href=\"https://cdn.example.com/font.woff2\" as=\"font\" type=\"font/woff2\" crossorigin><img src=\"https://cdn.example.com/chart.png\" alt=\"نمودار فروش\" crossorigin=\"anonymous\">","exercise":"یک فونت و تصویر CDN تعریف کن؛ بررسی کن سرور چه هدر CORS لازم دارد و چه زمانی درخواست مسدود می‌شود.","status":"published","sort_order":23,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-24","course_id":"html-advanced","title":"پخش ویدیوی آموزشی با track و caption","slug":"html-advanced-24","summary":"عنصر track زیرنویس و توضیح صوتی را به ویدیو متصل می‌کند؛ kind و srclang و label باید با فایل هماهنگ باشند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>عنصر track زیرنویس و توضیح صوتی را به ویدیو متصل می‌کند؛ kind و srclang و label باید با فایل هماهنگ باشند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;video controls preload=\"metadata\" poster=\"cover.jpg\"&gt;&lt;source src=\"lesson.mp4\" type=\"video/mp4\"&gt;&lt;track kind=\"captions\" src=\"fa.vtt\" srclang=\"fa\" label=\"فارسی\" default&gt;&lt;/video&gt;</code></pre><h3>تمرین</h3><p>برای ویدیوی آموزشی زیرنویس فارسی و انگلیسی اضافه کن و فایل WebVTT معتبر بساز.</p><h3>نکته فنی</h3><p>زیرنویس باید گفتار و صداهای مهم را پوشش دهد؛ صرف متن خودکار بررسی‌نشده کافی نیست.</p><h3>معیار موفقیت</h3><p>کاربر بتواند زیرنویس را انتخاب کند و زمان‌بندی VTT معتبر باشد.</p>","starter_code":"<video controls preload=\"metadata\" poster=\"cover.jpg\"><source src=\"lesson.mp4\" type=\"video/mp4\"><track kind=\"captions\" src=\"fa.vtt\" srclang=\"fa\" label=\"فارسی\" default></video>","exercise":"برای ویدیوی آموزشی زیرنویس فارسی و انگلیسی اضافه کن و فایل WebVTT معتبر بساز.","status":"published","sort_order":24,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-25","course_id":"html-advanced","title":"دسترسی‌پذیری رسانه با توضیح و transcript","slug":"html-advanced-25","summary":"رسانه آموزشی باید برای افراد ناشنوا، کم‌شنوا و کسانی که صدا ندارند جایگزین متنی فراهم کند؛ transcript محتوای گفتار و اطلاعات دیداری ضروری را پوشش می‌دهد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>رسانه آموزشی باید برای افراد ناشنوا، کم‌شنوا و کسانی که صدا ندارند جایگزین متنی فراهم کند؛ transcript محتوای گفتار و اطلاعات دیداری ضروری را پوشش می‌دهد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;figure&gt;&lt;video controls&gt;&lt;source src=\"lesson.mp4\" type=\"video/mp4\"&gt;&lt;/video&gt;&lt;figcaption&gt;آموزش ساخت فرم&lt;/figcaption&gt;&lt;/figure&gt;&lt;a href=\"lesson-transcript.html\"&gt;خواندن متن کامل ویدیو&lt;/a&gt;</code></pre><h3>تمرین</h3><p>برای یک ویدیوی کوتاه caption و transcript جداگانه تهیه کن و تفاوت کاربرد آن‌ها را شرح بده.</p><h3>نکته فنی</h3><p>figcaption عنوان رسانه است و جایگزین زیرنویس یا transcript نیست.</p><h3>معیار موفقیت</h3><p>محتوای صوتی و دیداری مهم بدون نیاز به پخش ویدیو قابل دریافت باشد.</p>","starter_code":"<figure><video controls><source src=\"lesson.mp4\" type=\"video/mp4\"></video><figcaption>آموزش ساخت فرم</figcaption></figure><a href=\"lesson-transcript.html\">خواندن متن کامل ویدیو</a>","exercise":"برای یک ویدیوی کوتاه caption و transcript جداگانه تهیه کن و تفاوت کاربرد آن‌ها را شرح بده.","status":"published","sort_order":25,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-26","course_id":"html-advanced","title":"طراحی تجربه چاپ با ساختار معنایی","slug":"html-advanced-26","summary":"ساختار چاپ باید ترتیب خواندن و اطلاعات ضروری را حفظ کند؛ کنترل‌های تعاملی غیرضروری نباید در نسخه چاپی غالب باشند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>ساختار چاپ باید ترتیب خواندن و اطلاعات ضروری را حفظ کند؛ کنترل‌های تعاملی غیرضروری نباید در نسخه چاپی غالب باشند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;main&gt;&lt;article&gt;&lt;h1&gt;گزارش دوره&lt;/h1&gt;&lt;p&gt;خلاصه پیشرفت دانش‌آموز&lt;/p&gt;&lt;a href=\"/details\"&gt;جزئیات آنلاین&lt;/a&gt;&lt;/article&gt;&lt;/main&gt;</code></pre><h3>تمرین</h3><p>یک گزارش قابل چاپ طراحی کن؛ مشخص کن کدام داده‌ها باید در چاپ باقی بمانند و کدام کنترل‌ها فقط برای صفحه‌اند.</p><h3>نکته فنی</h3><p>قواعد چاپ عمدتاً در CSS @media print هستند؛ HTML باید معنای محتوا را درست ارائه کند.</p><h3>معیار موفقیت</h3><p>بدون کنترل‌های تعاملی نیز گزارش چاپی قابل فهم باشد.</p>","starter_code":"<main><article><h1>گزارش دوره</h1><p>خلاصه پیشرفت دانش‌آموز</p><a href=\"/details\">جزئیات آنلاین</a></article></main>","exercise":"یک گزارش قابل چاپ طراحی کن؛ مشخص کن کدام داده‌ها باید در چاپ باقی بمانند و کدام کنترل‌ها فقط برای صفحه‌اند.","status":"published","sort_order":26,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-27","course_id":"html-advanced","title":"بهبود سازگاری با زبان و نویسه‌های ترکیبی","slug":"html-advanced-27","summary":"زبان‌های ترکیبی، نام‌ها و متن‌های با جهت متفاوت نیازمند نشانه‌گذاری دقیق‌اند؛ bdi متن با جهت ناشناخته را ایزوله می‌کند و bdo جهت را به‌زور تغییر می‌دهد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>زبان‌های ترکیبی، نام‌ها و متن‌های با جهت متفاوت نیازمند نشانه‌گذاری دقیق‌اند؛ bdi متن با جهت ناشناخته را ایزوله می‌کند و bdo جهت را به‌زور تغییر می‌دهد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;p&gt;شناسه کاربر: &lt;bdi&gt;user_علی_27&lt;/bdi&gt;&lt;/p&gt;&lt;p&gt;کد: &lt;bdi&gt;AB-1209&lt;/bdi&gt;&lt;/p&gt;</code></pre><h3>تمرین</h3><p>در یک فهرست فارسی، نام کاربری لاتین و کدهای ترکیبی قرار بده و از bdi در جای درست استفاده کن.</p><h3>نکته فنی</h3><p>bdo را برای اصلاح عمومی متن به کار نبر؛ جهت واقعی محتوا را حفظ کن.</p><h3>معیار موفقیت</h3><p>ترکیب فارسی و لاتین بدون به‌هم‌ریختگی نمایش داده شود.</p>","starter_code":"<p>شناسه کاربر: <bdi>user_علی_27</bdi></p><p>کد: <bdi>AB-1209</bdi></p>","exercise":"در یک فهرست فارسی، نام کاربری لاتین و کدهای ترکیبی قرار بده و از bdi در جای درست استفاده کن.","status":"published","sort_order":27,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-28","course_id":"html-advanced","title":"ساختاردهی محتوای زمان‌مند و داده‌های ماشین‌خوان","slug":"html-advanced-28","summary":"داده زمان باید هم برای انسان و هم ماشین خوانا باشد؛ time با datetime مقدار استاندارد قابل پردازش ارائه می‌کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>داده زمان باید هم برای انسان و هم ماشین خوانا باشد؛ time با datetime مقدار استاندارد قابل پردازش ارائه می‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;time datetime=\"2026-11-07T18:30:00+04:30\"&gt;۷ نوامبر ۲۰۲۶، ساعت ۱۸:۳۰&lt;/time&gt;</code></pre><h3>تمرین</h3><p>برای تاریخ انتشار، مهلت تحویل و مدت یک رویداد از time با datetime معتبر استفاده کن.</p><h3>نکته فنی</h3><p>متن نمایشی و مقدار machine-readable باید به یک زمان اشاره کنند.</p><h3>معیار موفقیت</h3><p>مقدار datetime معتبر و با متن قابل مشاهده سازگار باشد.</p>","starter_code":"<time datetime=\"2026-11-07T18:30:00+04:30\">۷ نوامبر ۲۰۲۶، ساعت ۱۸:۳۰</time>","exercise":"برای تاریخ انتشار، مهلت تحویل و مدت یک رویداد از time با datetime معتبر استفاده کن.","status":"published","sort_order":28,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-29","course_id":"html-advanced","title":"ارتقای تدریجی قابلیت‌ها بدون وابستگی اجباری","slug":"html-advanced-29","summary":"Progressive enhancement یعنی محتوای اصلی بدون قابلیت‌های اضافی هم در دسترس باشد؛ قابلیت‌های پیشرفته پس از آن افزوده می‌شوند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>Progressive enhancement یعنی محتوای اصلی بدون قابلیت‌های اضافی هم در دسترس باشد؛ قابلیت‌های پیشرفته پس از آن افزوده می‌شوند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;form action=\"/search\" method=\"get\"&gt;&lt;label for=\"q\"&gt;جست‌وجو&lt;/label&gt;&lt;input id=\"q\" name=\"q\"&gt;&lt;button&gt;جست‌وجو&lt;/button&gt;&lt;/form&gt;</code></pre><h3>تمرین</h3><p>یک جست‌وجوی ساده بساز که بدون JavaScript نیز با GET کار کند؛ سپس قابلیت پیشنهاد زنده را به‌عنوان افزونه طراحی کن.</p><h3>نکته فنی</h3><p>از ابتدا عملکرد اصلی را به JavaScript وابسته نکن.</p><h3>معیار موفقیت</h3><p>عملکرد پایه با خاموش بودن JavaScript قابل استفاده باشد.</p>","starter_code":"<form action=\"/search\" method=\"get\"><label for=\"q\">جست‌وجو</label><input id=\"q\" name=\"q\"><button>جست‌وجو</button></form>","exercise":"یک جست‌وجوی ساده بساز که بدون JavaScript نیز با GET کار کند؛ سپس قابلیت پیشنهاد زنده را به‌عنوان افزونه طراحی کن.","status":"published","sort_order":29,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-30","course_id":"html-advanced","title":"طراحی HTML مقاوم در برابر محتوای ناقص","slug":"html-advanced-30","summary":"HTML مقاوم باید در برابر داده ناقص همچنان قابل فهم بماند؛ fallback و محتوای جایگزین بخشی از طراحی است. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>HTML مقاوم باید در برابر داده ناقص همچنان قابل فهم بماند؛ fallback و محتوای جایگزین بخشی از طراحی است.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;picture&gt;&lt;source srcset=\"diagram.webp\" type=\"image/webp\"&gt;&lt;img src=\"diagram.png\" alt=\"نمودار مراحل ثبت‌نام\"&gt;&lt;/picture&gt;&lt;noscript&gt;&lt;p&gt;برای امکانات تعاملی، JavaScript را فعال کن؛ محتوای اصلی در دسترس است.&lt;/p&gt;&lt;/noscript&gt;</code></pre><h3>تمرین</h3><p>یک صفحه آموزشی طراحی کن که تصویر فرمت جدید یا اسکریپت آن بارگیری نشد، پیام و محتوای اصلی همچنان قابل استفاده باشد.</p><h3>نکته فنی</h3><p>noscript جایگزین طراحی کامل بدون JavaScript نیست؛ فقط پیام/محتوای جایگزین ارائه می‌کند.</p><h3>معیار موفقیت</h3><p>شکست یک منبع، کل محتوای آموزشی را غیرقابل استفاده نکند.</p>","starter_code":"<picture><source srcset=\"diagram.webp\" type=\"image/webp\"><img src=\"diagram.png\" alt=\"نمودار مراحل ثبت‌نام\"></picture><noscript><p>برای امکانات تعاملی، JavaScript را فعال کن؛ محتوای اصلی در دسترس است.</p></noscript>","exercise":"یک صفحه آموزشی طراحی کن که تصویر فرمت جدید یا اسکریپت آن بارگیری نشد، پیام و محتوای اصلی همچنان قابل استفاده باشد.","status":"published","sort_order":30,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-31","course_id":"html-advanced","title":"ارزیابی ساختار با اعتبارسنجی و درخت دسترس‌پذیری","slug":"html-advanced-31","summary":"اعتبارسنجی HTML خطاهای ساختاری را پیدا می‌کند؛ درخت دسترس‌پذیری نشان می‌دهد فناوری کمکی چه نام و نقشی دریافت می‌کند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>اعتبارسنجی HTML خطاهای ساختاری را پیدا می‌کند؛ درخت دسترس‌پذیری نشان می‌دهد فناوری کمکی چه نام و نقشی دریافت می‌کند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;main&gt;&lt;h1&gt;ثبت‌نام&lt;/h1&gt;&lt;form&gt;&lt;label for=\"name\"&gt;نام&lt;/label&gt;&lt;input id=\"name\" name=\"name\" required&gt;&lt;button&gt;ارسال&lt;/button&gt;&lt;/form&gt;&lt;/main&gt;</code></pre><h3>تمرین</h3><p>یک صفحه را با validator بررسی کن، سپس در ابزار توسعه‌دهنده درخت دسترس‌پذیری را باز کن و سه ایراد را مستند کن.</p><h3>نکته فنی</h3><p>validator به‌تنهایی کیفیت دسترس‌پذیری یا تجربه کاربری را تضمین نمی‌کند.</p><h3>معیار موفقیت</h3><p>خطاهای معتبر رفع شوند و نقش و نام کنترل‌ها در accessibility tree دیده شود.</p>","starter_code":"<main><h1>ثبت‌نام</h1><form><label for=\"name\">نام</label><input id=\"name\" name=\"name\" required><button>ارسال</button></form></main>","exercise":"یک صفحه را با validator بررسی کن، سپس در ابزار توسعه‌دهنده درخت دسترس‌پذیری را باز کن و سه ایراد را مستند کن.","status":"published","sort_order":31,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-32","course_id":"html-advanced","title":"ممیزی صفحه برای خزنده و کاربر صفحه‌خوان","slug":"html-advanced-32","summary":"ممیزی حرفه‌ای باید ترتیب headingها، landmarkها، نام کنترل‌ها، متن جایگزین و پیوندهای تکراری را بررسی کند؛ ارزیابی خودکار کافی نیست. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>ممیزی حرفه‌ای باید ترتیب headingها، landmarkها، نام کنترل‌ها، متن جایگزین و پیوندهای تکراری را بررسی کند؛ ارزیابی خودکار کافی نیست.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;main&gt;&lt;h1&gt;دوره‌ها&lt;/h1&gt;&lt;section aria-labelledby=\"popular\"&gt;&lt;h2 id=\"popular\"&gt;محبوب&lt;/h2&gt;&lt;ul&gt;&lt;li&gt;&lt;a href=\"/html\"&gt;دوره HTML&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;&lt;/section&gt;&lt;/main&gt;</code></pre><h3>تمرین</h3><p>برای صفحه‌ای با چند بخش، یک چک‌لیست ممیزی بساز و با صفحه‌خوان یا پیمایش صفحه‌کلید موارد را دستی بررسی کن.</p><h3>نکته فنی</h3><p>امتیاز ابزار خودکار معادل دسترس‌پذیری کامل نیست.</p><h3>معیار موفقیت</h3><p>حداقل یک آزمون خودکار و یک آزمون دستی مستند شود.</p>","starter_code":"<main><h1>دوره‌ها</h1><section aria-labelledby=\"popular\"><h2 id=\"popular\">محبوب</h2><ul><li><a href=\"/html\">دوره HTML</a></li></ul></section></main>","exercise":"برای صفحه‌ای با چند بخش، یک چک‌لیست ممیزی بساز و با صفحه‌خوان یا پیمایش صفحه‌کلید موارد را دستی بررسی کن.","status":"published","sort_order":32,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-33","course_id":"html-advanced","title":"طراحی صفحه خطا و وضعیت‌های خالی","slug":"html-advanced-33","summary":"صفحه وضعیت خالی و خطا باید دلیل و مسیر اقدام بعدی را روشن کند؛ پیام نباید فقط یک کد یا رنگ باشد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>صفحه وضعیت خالی و خطا باید دلیل و مسیر اقدام بعدی را روشن کند؛ پیام نباید فقط یک کد یا رنگ باشد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;main&gt;&lt;h1&gt;دوره‌ای پیدا نشد&lt;/h1&gt;&lt;p&gt;این دوره هنوز منتشر نشده است.&lt;/p&gt;&lt;a href=\"/courses\"&gt;مشاهده همه دوره‌ها&lt;/a&gt;&lt;/main&gt;</code></pre><h3>تمرین</h3><p>برای حالت خالی، خطای ۴۰۴ و خطای بارگیری سه صفحه مجزا بساز و برای هرکدام مسیر بازیابی تعریف کن.</p><h3>نکته فنی</h3><p>خطای سرور را به‌عنوان نبودن محتوا نمایش نده؛ وضعیت‌ها معنای متفاوت دارند.</p><h3>معیار موفقیت</h3><p>کاربر دلیل وضعیت و اقدام بعدی را بفهمد.</p>","starter_code":"<main><h1>دوره‌ای پیدا نشد</h1><p>این دوره هنوز منتشر نشده است.</p><a href=\"/courses\">مشاهده همه دوره‌ها</a></main>","exercise":"برای حالت خالی، خطای ۴۰۴ و خطای بارگیری سه صفحه مجزا بساز و برای هرکدام مسیر بازیابی تعریف کن.","status":"published","sort_order":33,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-34","course_id":"html-advanced","title":"ساخت الگوی ناوبری عمیق برای سایت چندصفحه‌ای","slug":"html-advanced-34","summary":"ناوبری عمیق در سایت چندصفحه‌ای باید مسیر فعلی، بخش‌های اصلی و پیوندهای بازگشت را مشخص کند؛ ساختار باید در همه صفحات سازگار بماند. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>ناوبری عمیق در سایت چندصفحه‌ای باید مسیر فعلی، بخش‌های اصلی و پیوندهای بازگشت را مشخص کند؛ ساختار باید در همه صفحات سازگار بماند.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;nav aria-label=\"مسیر صفحه\"&gt;&lt;ol&gt;&lt;li&gt;&lt;a href=\"/\"&gt;خانه&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;a href=\"/academy\"&gt;آکادمی&lt;/a&gt;&lt;/li&gt;&lt;li aria-current=\"page\"&gt;HTML پیشرفته&lt;/li&gt;&lt;/ol&gt;&lt;/nav&gt;</code></pre><h3>تمرین</h3><p>برای سه صفحه تو‌در‌تو breadcrumb بساز و aria-current را فقط روی صفحه جاری قرار بده.</p><h3>نکته فنی</h3><p>breadcrumb جایگزین منوی اصلی نیست و نباید مسیر ساختگی نشان دهد.</p><h3>معیار موفقیت</h3><p>مسیر واقعی صفحه و وضعیت جاری برای فناوری کمکی مشخص باشد.</p>","starter_code":"<nav aria-label=\"مسیر صفحه\"><ol><li><a href=\"/\">خانه</a></li><li><a href=\"/academy\">آکادمی</a></li><li aria-current=\"page\">HTML پیشرفته</li></ol></nav>","exercise":"برای سه صفحه تو‌در‌تو breadcrumb بساز و aria-current را فقط روی صفحه جاری قرار بده.","status":"published","sort_order":34,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-35","course_id":"html-advanced","title":"پروژه نهایی: وب‌سایت مستندات چندزبانه","slug":"html-advanced-35","summary":"پروژه نهایی باید چند صفحه واقعی، ناوبری یکپارچه، metadata یکتا، ساختار معنایی، رسانه دسترس‌پذیر و fallback داشته باشد. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>پروژه نهایی باید چند صفحه واقعی، ناوبری یکپارچه، metadata یکتا، ساختار معنایی، رسانه دسترس‌پذیر و fallback داشته باشد.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;header&gt;&lt;a href=\"/\"&gt;آکادمی NEXORA FORGE&lt;/a&gt;&lt;nav aria-label=\"اصلی\"&gt;&lt;a href=\"/courses\"&gt;دوره‌ها&lt;/a&gt;&lt;/nav&gt;&lt;/header&gt;&lt;main&gt;&lt;article&gt;&lt;h1&gt;HTML پیشرفته&lt;/h1&gt;&lt;p&gt;مسیر یادگیری استاندارد وب&lt;/p&gt;&lt;/article&gt;&lt;/main&gt;&lt;footer&gt;© NEXORA FORGE&lt;/footer&gt;</code></pre><h3>تمرین</h3><p>یک وب‌سایت مستندات سه‌صفحه‌ای بساز: خانه، فهرست دوره‌ها و صفحه درس. برای هر صفحه عنوان، توضیح، canonical، breadcrumb و ساختار معنایی مستقل قرار بده.</p><h3>نکته فنی</h3><p>کپی‌کردن یک metadata ثابت برای همه صفحات خطاست؛ هر URL باید اطلاعات متناسب خودش را داشته باشد.</p><h3>معیار موفقیت</h3><p>هر سه صفحه با پیوندهای واقعی، عنوان یکتا، دسترس‌پذیری پایه و HTML معتبر کار کنند.</p>","starter_code":"<header><a href=\"/\">آکادمی NEXORA FORGE</a><nav aria-label=\"اصلی\"><a href=\"/courses\">دوره‌ها</a></nav></header><main><article><h1>HTML پیشرفته</h1><p>مسیر یادگیری استاندارد وب</p></article></main><footer>© NEXORA FORGE</footer>","exercise":"یک وب‌سایت مستندات سه‌صفحه‌ای بساز: خانه، فهرست دوره‌ها و صفحه درس. برای هر صفحه عنوان، توضیح، canonical، breadcrumb و ساختار معنایی مستقل قرار بده.","status":"published","sort_order":35,"estimated_minutes":40},{"id":"curriculum-324-html-advanced-36","course_id":"html-advanced","title":"ارزیابی نهایی استاندارد، امنیت و کیفیت HTML","slug":"html-advanced-36","summary":"در ارزیابی نهایی باید صحت استاندارد، امنیت، سازگاری، دسترس‌پذیری و عملکرد را جداگانه بررسی کنی و شواهد آزمون را ثبت کنی. این درس بر کاربرد واقعی، محدودیت‌ها و آزمون عملی تمرکز دارد.","content_html":"<h3>هدف درس</h3><p>در ارزیابی نهایی باید صحت استاندارد، امنیت، سازگاری، دسترس‌پذیری و عملکرد را جداگانه بررسی کنی و شواهد آزمون را ثبت کنی.</p><h3>نمونه و بررسی</h3><p>نمونه زیر را در فایل مناسب قرار بده. هر جا JavaScript لازم است، آن را در فایل جداگانه اجرا کن و وابستگی را درک کن.</p><pre><code>&lt;main&gt;&lt;h1&gt;گزارش ممیزی HTML&lt;/h1&gt;&lt;ol&gt;&lt;li&gt;اعتبارسنجی ساختار&lt;/li&gt;&lt;li&gt;آزمون صفحه‌کلید&lt;/li&gt;&lt;li&gt;بررسی metadata&lt;/li&gt;&lt;li&gt;بررسی منابع خارجی&lt;/li&gt;&lt;/ol&gt;&lt;/main&gt;</code></pre><h3>تمرین</h3><p>پروژه نهایی را با یک جدول ممیزی ارزیابی کن؛ برای هر ایراد، شدت، اثر، روش بازتولید و اصلاح را بنویس.</p><h3>نکته فنی</h3><p>عبارت «بدون خطا» را بدون آزمون مستند استفاده نکن.</p><h3>معیار موفقیت</h3><p>گزارش شامل نتیجه آزمون، ایرادهای باقی‌مانده و محدودیت‌های بررسی باشد.</p>","starter_code":"<main><h1>گزارش ممیزی HTML</h1><ol><li>اعتبارسنجی ساختار</li><li>آزمون صفحه‌کلید</li><li>بررسی metadata</li><li>بررسی منابع خارجی</li></ol></main>","exercise":"پروژه نهایی را با یک جدول ممیزی ارزیابی کن؛ برای هر ایراد، شدت، اثر، روش بازتولید و اصلاح را بنویس.","status":"published","sort_order":36,"estimated_minutes":40}]$lessons$::jsonb) as x(id text,course_id text,title text,slug text,summary text,content_html text,starter_code text,exercise text,status text,sort_order integer,estimated_minutes integer)
join (values
('html','html','beginner'),('html-intermediate','html','intermediate'),('html-advanced','html','advanced'),
('css','css','beginner'),('css-intermediate','css','intermediate'),('css-advanced','css','advanced'),
('javascript','javascript','beginner'),('javascript-intermediate','javascript','intermediate'),('javascript-advanced','javascript','advanced')
) as cp(course_id,language_id,level_id) on cp.course_id=x.course_id
join public.academy_courses c on c.language_id=cp.language_id and c.level_id=cp.level_id
on conflict(id) do update set title=excluded.title,slug=excluded.slug,summary=excluded.summary,content_html=excluded.content_html,starter_code=excluded.starter_code,exercise=excluded.exercise,status='published',sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,archived_at=null,updated_at=now();
